const cfg = $('Config').first().json.config;
const w  = $('N00 · Whisper Transkription').first().json;
const ex = $('Dokumente zusammenfuehren').first().json;
const meta = $('N00pre · Input-Qualitaetspruefung').first().json;
const transcript = w.transcription || w.text ||
  (Array.isArray(w.segments) ? w.segments.map(s => s.text).join(' ') : '');
const dauer = Number(w.duration || w.audio_duration || 0);
const doku = ex.dokumente || '';
const luecken = [];
if (dauer && dauer < cfg.thresholds.audio_min_sek)
  luecken.push({ was: 'Audiodauer unter ' + (cfg.thresholds.audio_min_sek/60) + ' Min', wo: 'N00',
    konsequenz: 'Gespraechsinhalt evtl. unvollstaendig - Analyse weniger belastbar.' });
if (doku.trim().length < cfg.thresholds.pdf_min_chars)
  luecken.push({ was: 'PDF-Textextraktion lieferte sehr wenig Text (' + doku.trim().length + ' Zeichen)', wo: 'N00b',
    konsequenz: 'Moeglicherweise Bild-PDF. Dokumentbasierte Werte als [Fehlend] markieren.' });
return [{ json: {
  unternehmen: meta.Unternehmen || meta.unternehmen || '',
  datum: new Date().toISOString().slice(0, 10),
  transcript, dokumente: doku, dauer_sek: dauer, luecken_global: luecken
} }];

function parseLLM(nodeName){
  try {
    const r = $(nodeName).first().json;
    let c = (r && r.choices && r.choices[0] && r.choices[0].message && r.choices[0].message.content) || '';
    if (typeof c !== 'string') c = JSON.stringify(c);
    c = c.replace(/<think>[\s\S]*?<\/think>/g,'');
