const n05 = parseLLM('N05 · LLM'), n06 = parseLLM('N06 · LLM'), n07 = parseLLM('N07 · LLM');
const sc = (o) => { const v = Number(o && o.score); return isFinite(v) ? Math.max(0, Math.min(10, v)) : null; };
const parts = [['N02', sc(n02), g.N02], ['N03', sc(n03), g.N03], ['N05', sc(n05), g.N05], ['N06', sc(n06), g.N06], ['N07', sc(n07), g.N07]];
let wsum = 0, gsum = 0; const fehlende = [];
for (const [k, v, w] of parts) { if (v == null) fehlende.push(k); else { wsum += v * w; gsum += w; } }
const score100 = gsum > 0 ? Math.round((wsum / gsum) * 10) : 0;
function countFehlend(o) { let c = 0;
  if (o && Array.isArray(o.kennzeichnungen)) for (const k of o.kennzeichnungen) if (String(k.art||'').toLowerCase() === 'fehlend') c++;
  if (o && Array.isArray(o.luecken)) c += o.luecken.length; return c; }
const fehlendTotal = [n02,n03,n04,n05,n06,n07].reduce((a,o)=>a+countFehlend(o),0) + fehlende.length * 2;
const completeness = fehlendTotal <= 2 ? 'hoch' : (fehlendTotal <= 6 ? 'mittel' : 'gering');
const order = ['Stoppen','Vereinfachen','Nachschaerfen','Pilotieren','Weiterfuehren','Gezielt skalieren'];
function baseCat(s){ if(s>=80) return 'Gezielt skalieren'; if(s>=65) return 'Weiterfuehren'; if(s>=50) return 'Pilotieren'; if(s>=35) return 'Vereinfachen'; return 'Stoppen'; }
let cat = baseCat(score100);
if (completeness === 'mittel') cat = order[Math.max(0, order.indexOf(cat) - 1)];
if (completeness === 'gering') cat = 'Beobachten';
if (sc(n07) != null && sc(n07) <= 3 && order.indexOf(cat) > order.indexOf('Nachschaerfen')) cat = 'Nachschaerfen';
return [{ json: {
  score: score100, kategorie: cat, completeness,
  teilscores: parts.map(p => ({ node: p[0], score: p[1], gewicht: p[2] })),
  fehlende_teilscores: fehlende,
  regelwerk: 'Gewichteter Mittelwert (N02 20%, N03 15%, N05 30%, N06 20%, N07 15%) x10. '
    + 'Downgrade um 1 Stufe bei mittlerer Datenvollstaendigkeit, auf "Beobachten" bei geringer. '
    + 'Erzwungenes "Nachschaerfen" wenn Risiko-Score (N07) <= 3.'
} }];

